const products = [{ id: "p1", name: "Sac", price: 299 }];
const money = (value: number) => `${value} MAD`;
export default function Products() {
  return <ul>{products.map((p) => <li key={p.id}>{p.name} · {money(p.price)}</li>)}</ul>;
}

